INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Zentralelemente > Schnittstellen & Anschlüsse
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Schnittstellen und Anschlüsse eines Systems unabhängig von den Peripheriegeräten ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kompatibilität mit Geräten ist entscheidend"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität führt zu Problemen"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Schnittstellen immer die aktuellen Standards wie USB-Versionen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Standards beeinflussen Geschwindigkeit und Kompatibilität"}, {"text": "Nein", "correct": false, "because": "Aktuelle Standards sind oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Anzahl der Schnittstellen auf einem Mainboard unerheblich für die Systemerweiterung?', 2, '[{"text": "Nein", "correct": true, "because": "Anschlüsse bestimmen Erweiterungsmöglichkeiten"}, {"text": "Ja", "correct": false, "because": "Anzahl ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Schnittstellen und Anschlüsse ohne Rücksicht auf die Datenübertragungsrate geplant werden?', 2, '[{"text": "Nein", "correct": true, "because": "Übertragungsrate beeinflusst Leistung"}, {"text": "Ja", "correct": false, "because": "Leistung hängt von Rate ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind ältere Schnittstellen wie PS/2 in modernen Systemen immer nutzlos?', 2, '[{"text": "Nein", "correct": true, "because": "Können für spezielle Geräte nützlich sein"}, {"text": "Ja", "correct": false, "because": "Spezifische Anwendungen möglich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl von Schnittstellen und Anschlüssen am wichtigsten?', 3, '[{"text": "Kompatibilität mit Peripherie", "correct": true, "because": "Bestimmt Funktionalität"}, {"text": "Farbe der Anschlüsse", "correct": false, "because": "Ästhetisch, nicht technisch"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird primär für die Verbindung externer Speichermedien verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Weit verbreitet und vielseitig"}, {"text": "SATA", "correct": false, "because": "Intern, nicht extern primär"}, {"text": "PCIe", "correct": false, "because": "Für Erweiterungskarten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Anschluss ist für die Stromversorgung interner Laufwerke entscheidend?', 2, '[{"text": "SATA-Power", "correct": true, "because": "Versorgt interne Laufwerke"}, {"text": "USB-C", "correct": false, "because": "Externer Anschluss"}, {"text": "Molex", "correct": false, "because": "Älterer Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle bietet die höchste Datenübertragungsrate für Erweiterungskarten?', 3, '[{"text": "PCIe", "correct": true, "because": "Hohe Bandbreite für Grafikkarten etc."}, {"text": "USB 3.0", "correct": false, "because": "Schnell, aber extern"}, {"text": "SATA III", "correct": false, "because": "Für Speicher, nicht Karten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Anschluss wird für die Netzwerkverbindung am häufigsten genutzt?', 2, '[{"text": "Ethernet (RJ45)", "correct": true, "because": "Standard für kabelgebundenes Netzwerk"}, {"text": "HDMI", "correct": false, "because": "Für Video"}, {"text": "Thunderbolt", "correct": false, "because": "Multifunktional, nicht primär Netzwerk"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen sind auf modernen Mainboards typischerweise vorhanden?', 4, '[{"text": "USB", "correct": true, "because": "Für Peripheriegeräte"}, {"text": "SATA", "correct": true, "because": "Für Speichermedien"}, {"text": "PCIe", "correct": true, "because": "Für Erweiterungskarten"}, {"text": "Floppy-Controller", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl von Schnittstellen und Anschlüssen?', 3, '[{"text": "Peripheriegeräte", "correct": true, "because": "Bestimmen Kompatibilität"}, {"text": "Datenübertragungsrate", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Zukunftssicherheit", "correct": true, "because": "Neuere Standards bevorzugt"}, {"text": "Farbe der Kabel", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anschlüsse sind für die Videoausgabe relevant?', 3, '[{"text": "HDMI", "correct": true, "because": "Standard für Monitore"}, {"text": "DisplayPort", "correct": true, "because": "Hohe Auflösung und Bandbreite"}, {"text": "DVI", "correct": true, "because": "Älterer, aber nutzbarer Standard"}, {"text": "SATA", "correct": false, "because": "Für Speicher, nicht Video"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Wahl von Schnittstellen auftreten?', 4, '[{"text": "Inkompatibilität mit Geräten", "correct": true, "because": "Verbindung nicht möglich"}, {"text": "Zu wenige Anschlüsse", "correct": true, "because": "Begrenzt Erweiterung"}, {"text": "Veraltete Standards", "correct": true, "because": "Langsamere Übertragung"}, {"text": "Zu hohe Kosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen erhöhen die Flexibilität eines Systems?', 3, '[{"text": "USB-C", "correct": true, "because": "Multifunktional und schnell"}, {"text": "Thunderbolt", "correct": true, "because": "Hohe Bandbreite und Vielseitigkeit"}, {"text": "PCIe", "correct": true, "because": "Erweiterungskarten möglich"}, {"text": "PS/2", "correct": false, "because": "Älter und eingeschränkt"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) USB 3.0 ist schneller als USB 2.0. b) SATA ist für externe Geräte primär gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "USB 3.0 ja, SATA intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PCIe-Slots dienen der Systemerweiterung. b) HDMI überträgt keine Audiosignale.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "PCIe ja, HDMI mit Audio"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Thunderbolt bietet höhere Bandbreite als USB-C. b) Schnittstellen beeinflussen die Leistung nicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Thunderbolt ja, Leistung relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Anzahl der USB-Ports begrenzt Peripheriegeräte. b) Ältere Schnittstellen sind immer inkompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ports ja, ältere oft nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) SATA-Anschlüsse versorgen Laufwerke mit Strom. b) Schnittstellenwahl hängt von Kundenanforderungen ab.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "SATA nur Daten, Anforderungen ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),

